const secretReference = 'PASTORAL_ID_HMAC_KEY';
const secret = $env[secretReference];
const blocked = (reasonCode) => [{ json: { action: 'blocked', reasonCode, history: [], sendToModel: false } }];
if (!secret) return blocked('MISSING_HMAC_KEY');

// 此草稿只接受合成識別，不接 LINE webhook；秘密值與內部 ID 均不得輸出。
return [{ json: {
  draftOnly: true,
  webhookConnected: false,
  identityAlgorithm: 'HMAC-SHA256',
  identityEncoding: 'base64url',
  identityVersion: 'hmac-sha256-v1',
  consentRequiredExactlyTrue: true,
  retentionDays: 30,
  maxHistoryItems: 10,
  serverSideIdentityFilterRequired: true,
  verifyEveryItemIdentity: true,
  failClosed: true,
  blockedHistory: [],
  sendToModelOnBlocked: false,
  secretConfigured: true
} }];
